export default async ({ page, shot, wait }) => {
  await wait(800);
  await page.fill("#school-search", "Colorado Boulder");
  await wait(2500);
  await page.locator(".nb-results button").first().click();
  await page.getByRole("button", { name: "Read the terms" }).click();
  await wait(300);
  await shot("terms-dialog");
  console.log("focus in dialog:", await page.evaluate(() => !!document.activeElement?.closest("[role=dialog]")));
  await page.keyboard.press("Escape");
  console.log("dialog after Escape:", await page.locator("[role=dialog]").count());
  await page.getByLabel("I agree to the beta terms").check();
  await page.getByRole("button", { name: "Continue" }).click();
  await wait(2500);
  await page.getByRole("button", { name: "Sign in to Canvas" }).click();
  await wait(3500);
  await shot("first-sync-failed");
  await page.getByRole("button", { name: "Try again" }).click();
  await wait(4000);
  await shot("home-after-retry");
  await page.getByRole("tab", { name: "Study" }).click();
  await wait(2000);
  await shot("study-empty");
  await page.getByRole("button", { name: "Choose material" }).click();
  await wait(2500);
  await shot("settings-practice-material");
  // Import MATH 1300 Canvas material, then a bundled packet.
  const math = page.locator("li.packet", { hasText: "MATH 1300" }).first();
  await math.getByRole("button", { name: /Import selected/ }).click();
  await wait(2500);
  console.log("notice:", await page.locator(".notice, [role=alert]").allInnerTexts());
  await page.locator(".template-list li", { hasText: "MATH 1300" }).getByRole("button", { name: "Import" }).click();
  await wait(2000);
  console.log("notice:", await page.locator(".notice, [role=alert]").allInnerTexts());
  await page.getByRole("tab", { name: "Study" }).click();
  await wait(2500);
  await shot("study-offer");
  console.log("study buttons:", await page.locator("main button").allInnerTexts());
};
